-- pipeline/enabled-outlets
-- The outlets a collection run polls, in a fixed order.
--
-- Parameters, with the example values used to render this file:
--   $1 = true
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

select "id", "slug", "feed_url"
from "outlets"
where "outlets"."enabled" = $1
order by "outlets"."slug";
